-- 041 — Slice 4B (1/4): the company device register (DEC-35, DB v1.11 §3 company_devices).
-- Added: company_devices (+ indexes, triggers, RLS), register_company_device, assign_company_device, unassign_company_device,
--        set_company_device_status, list_company_devices.
-- The register records which company-issued phone belongs to which driver. A device key is generated by the app on the phone
-- (a random UUID kept in IndexedDB / localStorage): it identifies the browser install, not the hardware, it is UNTRUSTED and it
-- only ever FLAGS a submission made from another phone (DEC-35: flagged, never refused).
-- Who manages it: holders of driver.manage for the device's branch (fleet administrator company-wide, branch manager own
-- branch). No new permission key. DEC-24: nobody assigns, unassigns or changes the status of the device assigned to themselves.
-- No DELETE ever (lost / retired devices stay); every change is audited by trigger.

create table public.company_devices (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null references public.companies (id),
  branch_id uuid not null,
  device_key uuid not null,                               -- generated by the app on the phone; untrusted
  asset_tag text check (asset_tag = btrim(asset_tag) and length(asset_tag) between 1 and 60),
  label text check (label = btrim(label) and length(label) between 1 and 100),
  assigned_driver_id uuid,
  assigned_from timestamptz,
  assigned_to timestamptz,                                -- null while the assignment is open
  status text not null default 'active' check (status in ('active', 'lost', 'retired')),
  created_by uuid not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  foreign key (branch_id, company_id) references public.branches (id, company_id),
  foreign key (assigned_driver_id, company_id) references public.drivers (id, company_id),
  foreign key (created_by, company_id) references public.profiles (id, company_id),
  constraint company_devices_key_uq unique (company_id, device_key),      -- also covers the company_id FK
  unique (id, company_id),                                                -- target for composite FKs
  constraint company_devices_assignment_pair check ((assigned_driver_id is null) = (assigned_from is null)),
  constraint company_devices_assignment_order check (assigned_to is null or (assigned_from is not null and assigned_to >= assigned_from)),
  -- a lost or retired phone has no open assignment
  constraint company_devices_inactive_unassigned check (status = 'active' or assigned_driver_id is null or assigned_to is not null)
);
-- one OPEN assignment per driver (an open assignment = driver set and assigned_to null)
create unique index company_devices_one_open_per_driver_uq on public.company_devices (company_id, assigned_driver_id)
  where assigned_driver_id is not null and assigned_to is null;
create index company_devices_branch_company_idx   on public.company_devices (branch_id, company_id);
create index company_devices_driver_company_idx   on public.company_devices (assigned_driver_id, company_id);
create index company_devices_created_by_company_idx on public.company_devices (created_by, company_id);

create trigger company_devices_updated   before update on public.company_devices for each row execute function public.set_updated_at();
create trigger company_devices_immutable before update on public.company_devices for each row
  execute function public.prevent_column_change('id', 'company_id', 'branch_id', 'device_key', 'created_by', 'created_at');
create trigger company_devices_no_delete   before delete   on public.company_devices for each row       execute function public.forbid_delete();
create trigger company_devices_no_truncate before truncate on public.company_devices for each statement execute function public.forbid_delete();
create trigger company_devices_audit after insert or update or delete on public.company_devices
  for each row execute function public.audit_row_change();

comment on table public.company_devices is
  'DEC-35 company device register. device_key identifies a browser install on a phone and is untrusted: it only flags (inspections.device_flag), never refuses.';

alter table public.company_devices enable row level security;
revoke all on public.company_devices from public, anon, authenticated, service_role;
grant select on public.company_devices to authenticated, service_role;
-- managers of the device's branch only (driver.manage); every write goes through the functions below
create policy company_devices_select on public.company_devices for select to authenticated
  using (company_id = (select public.current_company_id()) and public.has_permission('driver.manage', branch_id));

-- ---------------------------------------------------------------- register
create function public.register_company_device(p_branch_id uuid, p_device_key uuid, p_asset_tag text, p_label text) returns uuid
language plpgsql security definer set search_path = '' as $$
declare
  v_company uuid := public.current_company_id();
  v_id uuid;
  d public.company_devices;
begin
  if auth.uid() is null or v_company is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_branch_id is null or p_device_key is null then
    raise exception 'a branch and the phone''s device key are required' using errcode = '22023';
  end if;
  if not exists (select 1 from public.branches b where b.id = p_branch_id and b.company_id = v_company) then
    raise exception 'branch not found' using errcode = 'P0002';
  end if;
  if not public.has_permission('driver.manage', p_branch_id) then
    raise exception 'missing permission driver.manage for this branch' using errcode = '42501';
  end if;
  select * into d from public.company_devices x where x.company_id = v_company and x.device_key = p_device_key;
  if found then
    -- an identical retry is a no-op; anything else is a clash
    if d.branch_id = p_branch_id and d.asset_tag is not distinct from nullif(btrim(p_asset_tag), '')
       and d.label is not distinct from nullif(btrim(p_label), '') then
      return d.id;
    end if;
    raise exception 'that phone is already registered' using errcode = '23505';
  end if;
  perform set_config('app.audit_reason', 'company device registered', true);
  insert into public.company_devices (company_id, branch_id, device_key, asset_tag, label, created_by)
  values (v_company, p_branch_id, p_device_key, nullif(btrim(p_asset_tag), ''), nullif(btrim(p_label), ''), auth.uid())
  returning id into v_id;
  perform set_config('app.audit_reason', '', true);
  return v_id;
end $$;

-- ---------------------------------------------------------------- assign / unassign
create function public.assign_company_device(p_device_id uuid, p_driver_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_company uuid := public.current_company_id();
  d public.company_devices;
  dr public.drivers;
begin
  if auth.uid() is null or v_company is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_reason is null or btrim(p_reason) = '' or length(p_reason) > 500 then
    raise exception 'a reason (1-500 characters) is required' using errcode = '22023';
  end if;
  select * into d from public.company_devices x where x.id = p_device_id and x.company_id = v_company for update;
  if not found then
    raise exception 'device not found' using errcode = 'P0002';
  end if;
  if not public.has_permission('driver.manage', d.branch_id) then
    raise exception 'missing permission driver.manage for this branch' using errcode = '42501';
  end if;
  select * into dr from public.drivers x where x.id = p_driver_id and x.company_id = v_company;
  if not found then
    raise exception 'driver not found' using errcode = 'P0002';
  end if;
  if dr.profile_id = auth.uid() then
    raise exception 'nobody may assign a device to themselves (DEC-24)' using errcode = '42501';
  end if;
  if dr.branch_id <> d.branch_id then
    raise exception 'the device and the driver are in different branches' using errcode = '22023';
  end if;
  if dr.active_status <> 'active' then
    raise exception 'that driver is inactive' using errcode = '22023';
  end if;
  if d.status <> 'active' then
    raise exception 'a % device cannot be assigned', d.status using errcode = '55000';
  end if;
  if d.assigned_driver_id is not null and d.assigned_to is null then
    raise exception 'this device is already assigned: unassign it first' using errcode = '55000';
  end if;
  if exists (select 1 from public.company_devices x where x.company_id = v_company and x.assigned_driver_id = dr.id and x.assigned_to is null) then
    raise exception 'that driver already has an issued device: unassign it first' using errcode = '23505';
  end if;
  perform set_config('app.audit_reason', left('device assigned: ' || btrim(p_reason), 500), true);
  update public.company_devices
     set assigned_driver_id = dr.id, assigned_from = now(), assigned_to = null
   where id = d.id;
  perform set_config('app.audit_reason', '', true);
end $$;

create function public.unassign_company_device(p_device_id uuid, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_company uuid := public.current_company_id();
  d public.company_devices;
  v_profile uuid;
begin
  if auth.uid() is null or v_company is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_reason is null or btrim(p_reason) = '' or length(p_reason) > 500 then
    raise exception 'a reason (1-500 characters) is required' using errcode = '22023';
  end if;
  select * into d from public.company_devices x where x.id = p_device_id and x.company_id = v_company for update;
  if not found then
    raise exception 'device not found' using errcode = 'P0002';
  end if;
  if not public.has_permission('driver.manage', d.branch_id) then
    raise exception 'missing permission driver.manage for this branch' using errcode = '42501';
  end if;
  if d.assigned_driver_id is null or d.assigned_to is not null then
    raise exception 'this device is not assigned' using errcode = '55000';
  end if;
  select dr.profile_id into v_profile from public.drivers dr where dr.id = d.assigned_driver_id;
  if v_profile = auth.uid() then
    raise exception 'nobody may change the device assigned to themselves (DEC-24)' using errcode = '42501';
  end if;
  perform set_config('app.audit_reason', left('device unassigned: ' || btrim(p_reason), 500), true);
  update public.company_devices set assigned_to = now() where id = d.id;
  perform set_config('app.audit_reason', '', true);
end $$;

-- ---------------------------------------------------------------- status (active <-> lost; retired is final)
create function public.set_company_device_status(p_device_id uuid, p_status text, p_reason text) returns void
language plpgsql security definer set search_path = '' as $$
declare
  v_company uuid := public.current_company_id();
  d public.company_devices;
  v_profile uuid;
begin
  if auth.uid() is null or v_company is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_status is null or p_status not in ('active', 'lost', 'retired') then
    raise exception 'unknown status %', p_status using errcode = '22023';
  end if;
  if p_reason is null or btrim(p_reason) = '' or length(p_reason) > 500 then
    raise exception 'a reason (1-500 characters) is required' using errcode = '22023';
  end if;
  select * into d from public.company_devices x where x.id = p_device_id and x.company_id = v_company for update;
  if not found then
    raise exception 'device not found' using errcode = 'P0002';
  end if;
  if not public.has_permission('driver.manage', d.branch_id) then
    raise exception 'missing permission driver.manage for this branch' using errcode = '42501';
  end if;
  if d.status = 'retired' then
    raise exception 'a retired device is final' using errcode = '55000';
  end if;
  if d.status = p_status then
    return;
  end if;
  if d.assigned_driver_id is not null and d.assigned_to is null then
    select dr.profile_id into v_profile from public.drivers dr where dr.id = d.assigned_driver_id;
    if v_profile = auth.uid() then
      raise exception 'nobody may change the device assigned to themselves (DEC-24)' using errcode = '42501';
    end if;
  end if;
  perform set_config('app.audit_reason', left('device marked ' || p_status || ': ' || btrim(p_reason), 500), true);
  update public.company_devices
     set status = p_status,
         assigned_to = case when p_status <> 'active' and assigned_driver_id is not null and assigned_to is null then now() else assigned_to end
   where id = d.id;
  perform set_config('app.audit_reason', '', true);
end $$;

-- ---------------------------------------------------------------- list (manager view)
create function public.list_company_devices(p_branch_id uuid default null)
returns table (id uuid, branch_id uuid, branch_name text, short_code text, asset_tag text, label text, status text,
               assigned_driver_id uuid, driver_employee_number text, driver_name text, assigned_from timestamptz, assigned_to timestamptz)
language plpgsql stable security definer set search_path = '' as $$
begin
  if auth.uid() is null or public.current_company_id() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  return query
    select d.id, d.branch_id, b.name, upper(left(replace(d.device_key::text, '-', ''), 8)), d.asset_tag, d.label, d.status,
           case when d.assigned_to is null then d.assigned_driver_id end,
           case when d.assigned_to is null then dr.employee_number end,
           case when d.assigned_to is null then p.display_name end,
           d.assigned_from, d.assigned_to
      from public.company_devices d
      join public.branches b on b.id = d.branch_id and b.company_id = d.company_id
      left join public.drivers dr on dr.id = d.assigned_driver_id and dr.company_id = d.company_id
      left join public.profiles p on p.id = dr.profile_id and p.company_id = dr.company_id
     where d.company_id = public.current_company_id()
       and public.has_permission('driver.manage', d.branch_id)
       and (p_branch_id is null or d.branch_id = p_branch_id)
     order by b.name, d.label nulls last, d.created_at;
end $$;

revoke all on function
  public.register_company_device(uuid, uuid, text, text), public.assign_company_device(uuid, uuid, text),
  public.unassign_company_device(uuid, text), public.set_company_device_status(uuid, text, text), public.list_company_devices(uuid)
  from public, anon, authenticated;
grant execute on function
  public.register_company_device(uuid, uuid, text, text), public.assign_company_device(uuid, uuid, text),
  public.unassign_company_device(uuid, text), public.set_company_device_status(uuid, text, text), public.list_company_devices(uuid)
  to authenticated;
